"""Complete offline terrain source comparison and exact native GIS downloads."""
from __future__ import annotations
import base64
import html
import json
import math
from pathlib import Path
import numpy as np
from PIL import Image


def previews(folder,z,change,fill,valid,hydro):
    folder=Path(folder);stride=max(1,math.ceil(max(z.shape)/1200));files=[];metadata={}
    for name,data,signed in [('elevation',z,False),('change',change,True),('fill',fill,False)]:
        values=data[::stride,::stride];keep=valid[::stride,::stride]
        all_valid=data[valid];actual_lo,actual_hi=float(all_valid.min()),float(all_valid.max())
        if signed:
            bound=max(abs(actual_lo),abs(actual_hi));lo,hi=-bound,bound
        else:
            lo,hi=float(all_valid.min()),float(all_valid.max())
            if actual_hi==actual_lo:lo=hi=actual_lo
        intensity=(np.full(values.shape,128,dtype='uint8') if hi==lo else np.clip((values-lo)/(hi-lo)*210+25,0,255).astype('uint8'))
        rgba=np.stack([intensity,intensity,intensity,np.where(keep,255,0).astype('uint8')],axis=-1)
        p=folder/(name+'.png');Image.fromarray(rgba).save(p);files.append(p)
        metadata[name]={'minimum_m':lo,'maximum_m':hi,'data_minimum_m':actual_lo,'data_maximum_m':actual_hi,'native_cell_stride':stride,'preview_shape':list(values.shape),'native_shape':list(z.shape),'sampling':'Every stride-th original cell; displayed preview is not an averaged analytical raster'}
    p=folder/'preview.json';p.write_text(json.dumps(metadata,indent=2),encoding='utf-8');files.append(p)
    return files


def write_report(workspace,folder,result):
    workspace,folder=Path(workspace),Path(folder);case=result['case'];rows=[]
    for v in result['variants']:
        vf=folder/v['name'];meta=json.loads((vf/'preview.json').read_text());images={}
        for key in ['elevation','change','fill']:
            images[key]='data:image/png;base64,'+base64.b64encode((vf/(key+'.png')).read_bytes()).decode('ascii')
        rows.append({'name':v['name'],'burn_depth_m':v['burn_depth_m'],'statistics':v['statistics'],'seconds':v['seconds'],'images':images,'previews':meta,'downloads':[{ 'label':Path(f['path']).name,'href':str(Path(f['path']).relative_to(folder.relative_to(workspace)))} for f in v['files'] if f['path'].endswith(('.tif','.csv'))]})
    data={'id':result['case_id'],'title':result['title'],'classification':case.get('source_classification'),'case':case,'variants':rows,'hydrography':result['hydrography'],'interpretation':result['interpretation']}
    encoded=json.dumps(data,ensure_ascii=False,allow_nan=False).replace('<','\\u003c')
    title=html.escape(result['title'])
    content='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Terrain source comparison</title>
<style>
:root{font:15px/1.5 system-ui,sans-serif;color:#202020;background:#f3f3f3}*{box-sizing:border-box}body{margin:0}main{max-width:1180px;margin:auto;padding:28px}header{border-bottom:2px solid #333;margin-bottom:24px}.eyebrow{font-size:12px;letter-spacing:.12em;text-transform:uppercase}h1{font-size:30px;line-height:1.2}h2{font-size:21px}h3{font-size:16px}section{margin:24px 0;padding:20px;background:white;border:1px solid #ccc}.banner{border-left:4px solid #555;padding:12px;background:#eee}.grid{display:grid;grid-template-columns:2fr 1fr;gap:24px}.controls{display:flex;flex-wrap:wrap;gap:16px;align-items:end}label{display:block;min-width:0}select,input,textarea,button{font:inherit;max-width:100%;border:1px solid #777;background:#fff;padding:9px;border-radius:0}select{min-width:180px}button{cursor:pointer}button:hover{background:#eee}a{color:#222;text-decoration:underline;text-underline-offset:3px}figure{margin:16px 0}figure img{display:block;width:100%;max-height:630px;object-fit:contain;background:repeating-conic-gradient(#ddd 0% 25%,white 0% 50%) 50%/12px 12px;border:1px solid #aaa;image-rendering:pixelated}.legend{display:flex;align-items:center;gap:12px}.legend span{height:12px;flex:1;background:linear-gradient(90deg,#191919,#ebebeb)}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-variant-numeric:tabular-nums}th,td{text-align:right;padding:9px;border-bottom:1px solid #ddd;white-space:nowrap}th:first-child,td:first-child{text-align:left}th{background:#eee}dt{font-weight:600}dd{margin:0 0 14px;overflow-wrap:anywhere}code{font-size:12px;overflow-wrap:anywhere}textarea{width:100%;min-height:140px}.note{font-size:13px;color:#555}.downloads{display:flex;flex-wrap:wrap;gap:10px}.record{overflow-wrap:anywhere;white-space:pre-wrap;font-size:12px}footer{padding:20px 0;border-top:1px solid #aaa}.sources li{margin:8px 0}@media(max-width:700px){main{padding:14px}.grid{grid-template-columns:1fr}section{padding:14px}h1{font-size:25px}.controls>*{width:100%}select{width:100%}}
</style><main><header><p class="eyebrow">Ecosystem Sciences · TokenJunkieLabs / terrain inputs</p><h1>'''+title+'''</h1><p>Compare retained terrain editions before selecting a new scientific run.</p></header>
<p class="banner" id="classification"></p><section><h2>Elevation changes</h2><div class="controls"><label>Terrain edition<br><select id="variant"></select></label><label>Map<br><select id="map"><option value="elevation">Elevation (metres)</option><option value="change">Change from original (metres)</option><option value="fill">Depression fill depth (metres)</option></select></label></div><div class="grid"><figure><img id="picture" alt="Selected terrain raster preview"><figcaption><p class="legend"><b id="minimum"></b><span></span><b id="maximum"></b></p><p class="note" id="sample"></p></figcaption></figure><div><h3>Selected edition</h3><dl id="numbers"></dl><p class="note">Positive change raises the surface; negative change lowers it. Fill volume is geometric change, not an estimate of available water storage.</p><div class="downloads" id="downloads"></div></div></div></section>
<section><h2>Full-domain comparison</h2><p>All finite valid cells are included. The computational DEM is not clipped to a reporting boundary.</p><div class="scroll"><table><thead><tr><th>Edition</th><th>Burn (m)</th><th>Changed cells</th><th>Changed ha</th><th>Raised max (m)</th><th>Lowered max (m)</th><th>Fill (m³)</th></tr></thead><tbody id="table"></tbody></table></div><p><a href="comparison.csv" download>Exact comparison CSV</a> · <a href="hydrography-mask.tif" download>Original-grid selected hydrography mask</a> · <a href="summary.json" download>Full source and calculation record</a></p></section>
<section><h2>Scientific interpretation</h2><p id="interpretation"></p><p>Spill-level filling removes closed depressions while retaining flat surfaces. Local lower-neighbour counts describe the elevation surface, not completed stream routing. The original native model still resolves flats and computes its own flow directions. Hydrography burning is an explicit scenario assumption; its depth and corridor width are not measured channel dimensions.</p><dl><dt>Original source</dt><dd id="source"></dd><dt>Hydrography selection</dt><dd id="hydro"></dd><dt>Boundary policy</dt><dd id="boundary"></dd></dl><details><summary>Complete saved case and original source identities</summary><pre class="record" id="case"></pre></details></section>
<section><h2>Saved working notes</h2><p>Notes and map choice are stored locally for this exact case. Export them for another browser or a receiving copy.</p><label>Interpretation and source decisions<textarea id="notes"></textarea></label><p><button id="export">Export notes and selection</button> <label style="display:inline">Import notes <input id="import" type="file" accept="application/json,.json"></label></p><p role="status" id="status"></p></section>
<footer><p class="note">Case <code id="identity"></code>. Full-resolution GeoTIFFs retain the original affine transform, CRS and valid-cell support.</p><p class="note">Method: Barnes, Lehman and Mulla (2014), <a href="https://doi.org/10.1016/j.cageo.2013.04.024">Priority-Flood</a>. Conditioning is an analytical input choice; genuine depressions and impoundments may be hydrologically important.</p></footer></main>
<script id="data" type="application/json">'''+encoded+'''</script><script>
'use strict';const D=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id),fmt=x=>typeof x==='number'?x.toLocaleString(undefined,{maximumFractionDigits:4}):String(x??'—');const key='terrain-case-notes:'+D.id;let saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}')}catch{}const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
$('variant').innerHTML=D.variants.map(v=>'<option>'+esc(v.name)+'</option>').join('');if(D.variants.some(v=>v.name===saved.variant))$('variant').value=saved.variant;if(['elevation','change','fill'].includes(saved.map))$('map').value=saved.map;$('notes').value=typeof saved.notes==='string'?saved.notes:'';
$('classification').textContent='Source classification: '+(D.classification||'Use the retained publisher/source record')+'. '+(D.classification==='simulated'?'This worked case uses the original simulated headwaters terrain.':'Conditioned surfaces are derived inputs; original elevations remain separately available.');$('interpretation').textContent=D.interpretation;$('source').textContent=(D.case.dem.source_title||D.case.dem.source_id)+' · '+D.case.dem.vintage;$('hydro').textContent=D.case.hydrography?((D.case.hydrography.source_title||D.case.hydrography.source_id)+' · '+D.hydrography.features+' original line features · corridor half-width '+D.case.corridor_half_width_m+' m'):'No stream burning selected';$('boundary').textContent=D.case.nodata_boundary==='edge-and-nodata'?'Valid outside-edge cells and cells touching NoData are outlet seeds. Missing elevations are retained as missing.':'Only valid outer raster edges are outlet seeds. Internal NoData is treated as a barrier; disconnected valid islands require an explicit boundary revision.';$('case').textContent=JSON.stringify(D.case,null,2);$('identity').textContent=D.id;
$('table').innerHTML=D.variants.map(v=>{const s=v.statistics;return '<tr><td>'+esc(v.name)+'</td>'+[v.burn_depth_m,s.changed_cells,s.changed_area_ha,s.maximum_raise_m,s.maximum_lower_m,s.fill_volume_m3].map(x=>'<td>'+fmt(x)+'</td>').join('')+'</tr>'}).join('');
function save(){try{localStorage.setItem(key,JSON.stringify({schema:'upstate.terrain-notes/v1',case_id:D.id,variant:$('variant').value,map:$('map').value,notes:$('notes').value}));$('status').textContent='Saved in this browser.'}catch(e){$('status').textContent='Browser storage unavailable. Use Export notes to retain this edit.'}}
function draw(){const v=D.variants.find(v=>v.name===$('variant').value),k=$('map').value,m=v.previews[k],s=v.statistics;$('picture').src=v.images[k];$('minimum').textContent=fmt(m.minimum_m)+' m';$('maximum').textContent=fmt(m.maximum_m)+' m';$('sample').textContent=m.native_cell_stride===1?'Every original cell is represented in this preview.':'Preview samples every '+m.native_cell_stride+'th original cell; analytical rasters and totals use all original cells.';$('numbers').innerHTML=[['Valid cells',s.valid_cells],['Missing cells',s.nodata_cells],['Changed hectares',s.changed_area_ha],['Filled regions',s.fill_regions],['Maximum raise (m)',s.maximum_raise_m],['Maximum lowering (m)',s.maximum_lower_m],['Flat / local-low cells',s.local_relief.flat_or_local_low_cells]].map(([k,v])=>'<dt>'+esc(k)+'</dt><dd>'+fmt(v)+'</dd>').join('');$('downloads').innerHTML=v.downloads.map(f=>'<a download href="'+esc(f.href)+'">'+esc(f.label)+'</a>').join('')}
for(const id of ['variant','map'])$(id).addEventListener('change',()=>{draw();save()});$('notes').addEventListener('input',save);$('export').onclick=()=>{const o={schema:'upstate.terrain-notes/v1',case_id:D.id,variant:$('variant').value,map:$('map').value,notes:$('notes').value},u=URL.createObjectURL(new Blob([JSON.stringify(o,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='terrain-notes-'+D.id.slice(0,12)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};$('import').onchange=async e=>{try{const o=JSON.parse(await e.target.files[0].text());if(o.schema!=='upstate.terrain-notes/v1'||o.case_id!==D.id||!D.variants.some(v=>v.name===o.variant)||!['elevation','change','fill'].includes(o.map)||typeof o.notes!=='string')throw Error('Select notes for this exact terrain case');$('variant').value=o.variant;$('map').value=o.map;$('notes').value=o.notes;draw();save()}catch(e){$('status').textContent=e.message}};draw();
</script></html>'''
    destination=folder/'report.html';destination.write_text(content,encoding='utf-8');return destination
